    # 两个三角形共享底边: 并成菱形 面积 3
    tri3 = [((0, 0), (2, 0), (0, 2)), ((0, 0), (2, 0), (2, 2))]
    assert abs(tri_union_area_vertical(tri3) - 3.0) < 1e-9

